  $(`#${type}_maxDistance`).val(val);
  $(`#${type}_maxDistance_value`).val(val);
  val = settings3[`${type}_rolloffFactor`] ?? 0.3;
  $(`#${type}_rolloffFactor`).val(val);
  $(`#${type}_rolloffFactor_value`).val(val);
  val = settings3[`${type}_posX`] ?? 0;
  $(`#${type}_posX`).val(val);
  $(`#${type}_posX_value`).val(val);
  val = settings3[`${type}_posY`] ?? 0;
  $(`#${type}_posY`).val(val);
  $(`#${type}_posY_value`).val(val);
  val = settings3[`${type}_posZ`] ?? 0;
  $(`#${type}_posZ`).val(val);
