  $("#offline_rendering_enabled").prop("checked", settings3.offline_rendering_enabled);
  $("#enable_lyrics_player").prop("checked", settings3.enable_lyrics_player);
  $("#enable_tts_voice").prop("checked", settings3.enable_tts_voice);
  $("#enable_narration_tts").prop("checked", settings3.enable_narration_tts);
